-- SQL 风格伪代码：Message + Inbox 先一起持久化
BEGIN;
INSERT INTO messages (message_id, chat_id, sender_id, body)
VALUES (:messageId, :chatId, :senderId, :body);

INSERT INTO inbox (recipient_id, message_id, chat_id, status)
SELECT participant_id, :messageId, :chatId, 'pending'
FROM chat_participants
WHERE chat_id = :chatId AND participant_id <> :senderId;
COMMIT;

-- COMMIT 后才做 WebSocket 实时推送。
-- 某个接收者 ack 后，只清理他的待投递记录。
DELETE FROM inbox
WHERE recipient_id = :recipientId
  AND message_id = :messageId;

PutItem Inbox {
  ...
  "expiresAt": 1735689600   # unix epoch seconds, now + 30d
}
# DynamoDB TTL attribute: rows past expiresAt are auto-deleted
# no cron job, no manual DELETE needed
